import {fitViewportSelection} from './viewport-presentation.js';
import * as THREE from 'three';
import {createViewportControls} from './viewport-controls.js';
import {editorAnimationFrame,cancelEditorAnimationFrame} from './detached-window.js';
import {worldAssetTypes,validWorldAsset,editMesh,terrainBrush,scatterFoliage,eraseFoliage,simplifyMesh} from './world-assets.js';
import {loadWorldVisual,worldBufferGeometry,disposeWorldVisual,updateWorldLODs} from './world-rendering.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class WorldAssetEditor{
 constructor(element,doc,files,hooks){this.element=element;this.doc=doc;this.files=files;this.hooks=hooks;this.vertices=new Set();this.faces=new Set();this.settings={mode:'raise',radius:2,strength:.5,layer:0,height:0,count:100,minDistance:.5,seed:1};this.epoch=0;this.stage=new THREE.Scene();this.stage.background=new THREE.Color('#20262d');this.camera=new THREE.PerspectiveCamera(45,1,.01,1000000);this.camera.position.set(16,16,16);const light=new THREE.HemisphereLight(0xdcecff,0x463a31,2),sun=new THREE.DirectionalLight(0xffffff,3);sun.position.set(10,20,10);this.stage.add(light,sun);this.renderer=new THREE.WebGLRenderer({antialias:true});this.renderer.setPixelRatio(Math.min(2,element.ownerDocument.defaultView.devicePixelRatio));this.render();this.controls=createViewportControls(this.camera,this.renderer.domElement,{target:new THREE.Vector3(),onFocus:()=>this.fit()});this.observer=new ResizeObserver(()=>{const r=this.renderer.domElement.getBoundingClientRect();if(r.width&&r.height){this.renderer.setSize(r.width,r.height,false);this.camera.aspect=r.width/r.height;this.camera.updateProjectionMatrix();}});this.observer.observe(this.renderer.domElement);const frame=()=>{if(this.disposed)return;if(this.element.offsetWidth){this.controls.update();this.stage.updateMatrixWorld();if(this.doc.kind==='lod'&&this.group)updateWorldLODs(this.group,this.camera);this.renderer.render(this.stage,this.camera);}this.frame=editorAnimationFrame(this.element,frame);};this.frame=editorAnimationFrame(this.element,frame);this.rebuild().then(()=>this.fit()).catch(e=>hooks.error(e.message));}
 edit(change){if(this.hooks.running())return;try{const draft=structuredClone(this.doc.data),result=change(draft),next=result||draft;if(!validWorldAsset(this.doc.kind,next))throw Error('월드 에셋 값·참조 범위를 확인하세요.');if(JSON.stringify(next)===JSON.stringify(this.doc.data))return;if(!this.stroke||!this.stroke.remembered){this.hooks.before();if(this.stroke)this.stroke.remembered=true;}this.doc.data=next;if(this.stroke)this.stroke.changed=true;else{this.hooks.change();this.render();}this.rebuild().catch(e=>this.hooks.error(e.message));}catch(e){this.hooks.error(e.message);}}
 read=async p=>p===this.doc.path?this.doc.data:this.hooks.read(p);
 async rebuild(){const epoch=++this.epoch,path=this.doc.path,group=await loadWorldVisual(path,this.read);if(this.disposed||epoch!==this.epoch){disposeWorldVisual(group);return;}if(this.group){this.group.removeFromParent();disposeWorldVisual(this.group);}this.group=group;this.stage.add(group);this.updateSelection();}
 fit(){if(!this.group)return;const box=new THREE.Box3().setFromObject(this.group);fitViewportSelection(this.camera,this.controls,box);}
 updateSelection(){if(this.selectionVisual){this.selectionVisual.removeFromParent();this.selectionVisual.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});}if(this.doc.kind!=='mesh')return;const group=new THREE.Group(),data=this.doc.data,lines=[];for(const face of this.faces){const ids=data.indices.slice(face*3,face*3+3);if(ids.length===3)for(let i=0;i<3;i++)lines.push(...data.vertices[ids[i]],...data.vertices[ids[(i+1)%3]]);}if(lines.length){const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(lines,3));const mesh=new THREE.LineSegments(geometry,new THREE.LineBasicMaterial({color:0x6dbaff,depthTest:false}));mesh.renderOrder=1000;group.add(mesh);}const points=[...this.vertices].filter(i=>data.vertices[i]).flatMap(i=>data.vertices[i]);if(points.length){const geometry=new THREE.BufferGeometry();geometry.setAttribute('position',new THREE.Float32BufferAttribute(points,3));const mesh=new THREE.Points(geometry,new THREE.PointsMaterial({color:0xf3bc62,size:6,sizeAttenuation:false,depthTest:false}));mesh.renderOrder=1001;group.add(mesh);}this.selectionVisual=group;this.stage.add(group);}

 selectOptions(kind,value){return '<option value="">없음</option>'+this.files().filter(f=>kind.includes(f.kind)&&f.path!==this.doc.path).map(f=>'<option value="'+esc(f.path)+'" '+(f.path===value?'selected':'')+'>'+esc(f.name)+'</option>').join('');}
 render(){const e=this.element,d=this.doc.data,kind=this.doc.kind;e.className='workspace-view world-asset-editor';const canvas=this.renderer.domElement;e.innerHTML='<header class="document-toolbar"><strong>'+esc(worldAssetTypes[kind].label)+' · '+esc(d.name)+'</strong><span class="toolbar-spacer"></span><button data-world-fit>프레이밍 F</button><button data-world-place>장면에 배치</button></header><div class="world-asset-layout"><main class="world-asset-preview"></main><aside class="world-asset-details"></aside></div>';e.querySelector('main').append(canvas);const props=e.querySelector('aside');
 if(kind==='mesh')props.innerHTML='<section><h3>선택 · '+this.vertices.size+' 정점 / '+this.faces.size+' 면</h3><label>모드<select data-world-selection><option value="face">면</option><option value="vertex" '+(this.selectionMode==='vertex'?'selected':'')+'>정점</option></select></label><div class="world-delta">'+[0,1,2].map((i)=>'<input data-world-delta="'+i+'" type="number" value="0" step=".1" aria-label="이동 '+['X','Y','Z'][i]+'">').join('')+'</div><button data-world-mesh="move">정점 이동</button><button data-world-mesh="subdivide">면 분할</button><label>압출 거리<input data-world-distance type="number" value="1" step=".1"></label><button data-world-mesh="extrude">면 압출</button><button data-world-mesh="flip">면 뒤집기</button><button data-world-mesh="deleteFaces">면 삭제</button><button data-world-mesh="uvXZ">XZ UV 투영</button><small>'+d.vertices.length+' 정점 · '+d.indices.length/3+' 삼각형</small></section>';
 if(kind==='terrain')props.innerHTML='<section><h3>지형 브러시</h3><label>도구<select data-world-setting="mode">'+[['raise','높이 올리기'],['lower','높이 내리기'],['flatten','높이 맞추기'],['smooth','평활화'],['paint','레이어 칠하기']].map(([k,l])=>'<option value="'+k+'" '+(this.settings.mode===k?'selected':'')+'>'+l+'</option>').join('')+'</select></label>'+this.number('반경','radius',.001,100000)+this.number('강도','strength',0,10000)+this.number('목표 높이','height',-10000,10000)+'<label>레이어<select data-world-setting="layer">'+d.layers.map((l,i)=>'<option value="'+i+'" '+(i===this.settings.layer?'selected':'')+'>'+esc(l.name)+'</option>').join('')+'</select></label><button data-world-layer>레이어 추가</button>'+d.layers.map((l,i)=>'<label>'+esc(l.name)+'<input type="color" data-world-layer-color="'+i+'" value="#'+l.color.map(c=>Math.round(c*255).toString(16).padStart(2,'0')).join('')+'"></label>').join('')+'<div class="world-delta">'+d.size.map((v,i)=>'<label>'+['가로','세로'][i]+'<input data-world-size="'+i+'" type="number" min=".001" value="'+v+'"></label>').join('')+'</div><small>'+d.resolution.join(' × ')+'</small></section>';
 if(kind==='foliage')props.innerHTML='<section><h3>폴리지</h3><label>메시<select data-world-ref="mesh">'+this.selectOptions(['mesh','terrain'],d.mesh)+'</select></label><label>지형<select data-world-ref="terrain">'+this.selectOptions(['terrain'],d.terrain)+'</select></label>'+this.number('브러시 반경','radius',.001,100000)+this.number('산포 수','count',0,1000000)+this.number('최소 간격','minDistance',.0001,10000)+this.number('시드','seed',0,4294967295)+'<button data-world-scatter>중심에 산포</button><button data-world-erase>중심에서 소거</button><small>'+d.instances.length+' 인스턴스</small></section>';
 if(kind==='lod')props.innerHTML='<section><h3>LOD 레벨</h3><label>기준<select data-world-lod-mode><option value="distance" '+(d.mode==='distance'?'selected':'')+'>거리</option><option value="screen" '+(d.mode==='screen'?'selected':'')+'>화면 높이</option></select></label><label>히스테리시스<input type="number" min="0" max=".5" step=".01" data-world-lod-field="hysteresis" value="'+d.hysteresis+'"></label><label>강제 레벨<input type="number" min="-1" max="'+(d.levels.length-1)+'" data-world-lod-field="forced" value="'+d.forced+'"></label>'+d.levels.map((l,i)=>'<div class="world-lod-level"><strong>LOD '+i+'</strong><select data-world-lod-asset="'+i+'">'+this.selectOptions(['mesh','terrain','foliage'],l.asset)+'</select><input data-world-lod-threshold="'+i+'" value="'+l.threshold+'" type="number" step=".01" min=".000001"><button data-world-lod-remove="'+i+'">삭제</button></div>').join('')+'<label>새 레벨<select data-world-lod-new>'+this.selectOptions(['mesh','terrain','foliage'],'')+'</select></label><button data-world-lod-add>레벨 추가</button><label>단순화 셀 크기<input data-world-simplify-size value=".25" type="number" min=".000001" step=".05"></label><button data-world-simplify '+(!d.levels.length?'disabled':'')+'>메시 LOD 생성</button></section>';
 canvas.oncontextmenu=event=>event.preventDefault();canvas.onpointerdown=event=>{if(event.button===0&&['terrain','foliage'].includes(this.doc.kind)){event.stopImmediatePropagation();this.stroke={remembered:false,changed:false};canvas.setPointerCapture(event.pointerId);}this.pointer(event);};canvas.onpointermove=event=>{if(this.stroke&&event.buttons&1)this.pointer(event);};canvas.onpointerup=canvas.onlostpointercapture=()=>{if(!this.stroke)return;const stroke=this.stroke;this.stroke=null;if(stroke.changed)this.hooks.change();this.render();};e.querySelector('[data-world-fit]').onclick=()=>this.fit();e.querySelector('[data-world-place]').onclick=()=>this.hooks.place();props.onchange=event=>this.change(event.target);props.onclick=event=>this.action(event.target.closest('button'));canvas.tabIndex=0;canvas.onkeydown=event=>{if(event.code==='KeyF'){event.preventDefault();this.fit();}};}
 number(label,key,min,max){return '<label>'+label+'<input type="number" data-world-setting="'+key+'" value="'+this.settings[key]+'" min="'+min+'" max="'+max+'" step="'+(key==='count'||key==='seed'?1:'.1')+'"></label>';}
 change(el){if(el.dataset.worldSetting){this.settings[el.dataset.worldSetting]=el.tagName==='SELECT'&&el.dataset.worldSetting==='mode'?el.value:Number(el.value);return;}if(el.hasAttribute('data-world-selection')){this.selectionMode=el.value;return;}if(el.dataset.worldRef)return this.edit(d=>{d[el.dataset.worldRef]=el.value;});if(el.hasAttribute('data-world-layer-color'))return this.edit(d=>{d.layers[Number(el.dataset.worldLayerColor)].color=[0,1,2].map(i=>parseInt(el.value.slice(i*2+1,i*2+3),16)/255);});if(el.hasAttribute('data-world-size'))return this.edit(d=>{d.size[Number(el.dataset.worldSize)]=Number(el.value);});if(el.hasAttribute('data-world-lod-mode'))return this.edit(d=>{d.mode=el.value;d.levels.forEach((l,i)=>l.threshold=d.mode==='distance'?.001+i*20:1/(i+1));});if(el.dataset.worldLodField)return this.edit(d=>{d[el.dataset.worldLodField]=Number(el.value);});if(el.hasAttribute('data-world-lod-asset'))return this.edit(d=>{d.levels[Number(el.dataset.worldLodAsset)].asset=el.value;});if(el.hasAttribute('data-world-lod-threshold'))return this.edit(d=>{d.levels[Number(el.dataset.worldLodThreshold)].threshold=Number(el.value);});}
 async action(button){if(!button)return;const e=this.element;try{if(button.dataset.worldMesh){const delta=[...e.querySelectorAll('[data-world-delta]')].map(el=>Number(el.value)),distance=Number(e.querySelector('[data-world-distance]').value);this.edit(d=>editMesh(d,{operation:button.dataset.worldMesh,vertices:[...this.vertices],faces:[...this.faces],delta,distance}));this.vertices.clear();this.faces.clear();this.updateSelection();this.render();}
 if(button.hasAttribute('data-world-layer'))this.edit(d=>{if(d.layers.length>=8)throw Error('지형 레이어는8개까지예요.');d.layers.push({name:'Layer '+(d.layers.length+1),color:[.5,.4,.3]});for(const w of d.weights)w.push(0);});
 if(button.hasAttribute('data-world-scatter')){const terrain=this.doc.data.terrain?await this.read(this.doc.data.terrain):undefined;this.edit(d=>scatterFoliage(d,{...this.settings,terrain}));}if(button.hasAttribute('data-world-erase'))this.edit(d=>eraseFoliage(d,[0,0],this.settings.radius));
 if(button.hasAttribute('data-world-lod-add')){const asset=e.querySelector('[data-world-lod-new]').value;if(asset)this.edit(d=>{d.levels.push({asset,threshold:d.mode==='distance'?(d.levels.at(-1)?.threshold||.001)+20:(d.levels.at(-1)?.threshold||1)/2});});}if(button.hasAttribute('data-world-lod-remove'))this.edit(d=>{d.levels.splice(Number(button.dataset.worldLodRemove),1);d.forced=-1;});
 if(button.hasAttribute('data-world-simplify')){const source=await this.read(this.doc.data.levels[0].asset),result=simplifyMesh(source,Number(e.querySelector('[data-world-simplify-size]').value)),created=await this.hooks.create('mesh',this.doc.data.name+'_LOD'+this.doc.data.levels.length,result);this.edit(d=>{d.levels.push({asset:created.path,threshold:d.mode==='distance'?(d.levels.at(-1)?.threshold||.001)+20:(d.levels.at(-1)?.threshold||1)/2});});}
 }catch(error){this.hooks.error(error.message);}}
 pointer(event){if(event.button!==0||this.hooks.running()||!this.group)return;const bounds=this.renderer.domElement.getBoundingClientRect(),ray=new THREE.Raycaster();ray.setFromCamera(new THREE.Vector2((event.clientX-bounds.left)/bounds.width*2-1,-(event.clientY-bounds.top)/bounds.height*2+1),this.camera);const hit=ray.intersectObject(this.group,true).find(v=>v.object.isMesh),point=hit?.point||ray.ray.intersectPlane(new THREE.Plane(new THREE.Vector3(0,1,0),0),new THREE.Vector3());if(!point)return;if(this.stroke){if(this.stroke.last&&point.distanceTo(this.stroke.last)<this.settings.radius*.1)return;this.stroke.last=point.clone();}if(this.doc.kind==='terrain')this.edit(d=>terrainBrush(d,{...this.settings,position:[point.x,point.z]}));if(this.doc.kind==='foliage')(this.doc.data.terrain?this.read(this.doc.data.terrain):Promise.resolve(undefined)).then(terrain=>{if(!this.disposed)this.edit(d=>event.shiftKey?eraseFoliage(d,[point.x,point.z],this.settings.radius):scatterFoliage(d,{...this.settings,center:[point.x,point.z],terrain}));});if(this.doc.kind==='mesh'&&hit){if(!event.ctrlKey){this.faces.clear();this.vertices.clear();}const ids=this.doc.data.indices.slice(hit.faceIndex*3,hit.faceIndex*3+3);if(this.selectionMode==='vertex'){const index=ids.reduce((a,b)=>new THREE.Vector3(...this.doc.data.vertices[a]).distanceTo(point)<new THREE.Vector3(...this.doc.data.vertices[b]).distanceTo(point)?a:b);this.vertices.add(index);}else{this.faces.add(hit.faceIndex);ids.forEach(i=>this.vertices.add(i));}this.render();this.updateSelection();}}
 dispose(){this.disposed=true;this.epoch++;cancelEditorAnimationFrame(this.element,this.frame);this.observer?.disconnect();this.controls?.dispose();if(this.group)disposeWorldVisual(this.group);if(this.selectionVisual){this.selectionVisual.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});this.selectionVisual.removeFromParent();}this.renderer.dispose();}
}
